647-8078-4d26-babc-a8c0c0502905", "type": "concept", "title": "Facts, values, stakeholders, options, and constraints"}, {"id": "29c4b616-821a-41e4-b4dc-c90af6f880f9", "type": "concept", "title": "Jonsen four-box method"}, {"id": "02b5cf7d-4f28-45d6-9669-39378a06f05b", "type": "concept", "title": "Ethics consultation and case memo structure"}]}]}, {"id": "a30246c6-7226-4c1d-bc1b-4f74ea119aa5", "type": "topic", "title": "Professional Codes, Duties, and Moral Identity", "description": "This topic connects ethical reasoning to professional obligations, role fidelity, accountability, and public trust.", "children": [{"id": "72576999-f266-42c5-944c-a174b3abd413", "type": "subtopic", "title": "Professional codes", "description": "Codes translate shared professional values into obligations.", "children": [{"id": "a61a5458-820f-41ec-9d45-e07e71dd2b11", "type": "concept", "title": "AMA Code of Medical Ethics"}, {"id": "d194f9fe-6c5a-4b27-aeb0-a145034c2f65", "type": "concept", "title": "ANA Code of Ethics for Nurses"}, {"id": "9ca87d4a-4e84-46e3-96fe-88903be9f0af", "type": "concept", "title": "Discipline-specific codes and scope of practice"}]}, {"id": "d84cfe66-ce91-4ed3-8bd2-c393d43d79a0", "type": "subtopic", "title": "Professional identity", "description": "Students learn that ethics is part of becoming a trusted clinician.", "children": [{"id": "f90a3dc9-6d9b-4627-a642-bd070aff8336", "type": "concept", "title": "Fiduciary duty"}, {"id": "f246741d-b4b0-4435-ac7a-93eebac2dcd8", "type": "concept", "title": "Accountability and integrity"}, {"id": "8b650846-f2c7-4858-89da-87fd8a7042c4", "type": "concept", "title": "Boundaries and professional conduct"}]}, {"id": "1601577c-5ec0-4991-84b8-ae890b505631", "type": "subtopic", "title": "Obligations to society", "description": "Healthcare professions serve patients and the public.", "children": [{"id": "e48a3301-d31a-4dd2-934a-a9b8af0cb11e", "type": "concept", "title": "Advocacy"}, {"id": "40ac9555-c4f9-4e28-b1b3-9f9c177ac095", "type": "concept", "title": "Stewardship"}, {"id": "ca4f40b5-e589-49bc-89f1-fa5aaa71afbe", "type": "concept", "title": "Public trust and social contract"}]}]}, {"id": "63b35947-a1fd-4b2f-9331-9c0d456901cb", "type": "topic", "title": "Patient Autonomy, Informed Consent, and Decisional Capacity", "description": "Students learn how patients make informed choices and when clinicians must assess capacity, support understanding, or use surrogate processes.", "children": [{"id": "d70e4e71-b423-4c3d-88b6-c2f0ed1711e0", "type": "subtopic", "title": "Informed consent", "description": "Consent protects patient self-determination and supports shared decision-making.", "children": [{"id": "e1205b70-b6c0-48ae-9ed8-70c227d6fed3", "type": "concept", "title": "Disclosure, understanding, voluntariness, and authorization"}, {"id": "5bad903f-e5ad-4f5d-90bf-dee684361e0e", "type": "concept", "title": "Risks, benefits, alternatives, and refusal"}, {"id": "b8c43644-c2ca-458a-858e-39038bcb7e2d", "type": "concept", "title": "Therapeutic privilege and its limits"}]}, {"id": "fa722b6c-1d7b-4ade-9263-5a850060e380", "type": "subtopic", "title": "Capacity", "description": "Capacity is decision-specific and can fluctuate.", "children": [{"id": "6b8155db-0c34-4a9d-a071-8e511cb9f30f", "type": "concept", "title": "Understanding, appreciation, reasoning, and expressing a choice"}, {"id": "48fe9cac-2968-419b-ab65-305d179661de", "type": "concept", "title": "Delirium, impairment, coercion, and communication barriers"}, {"id": "13b964ea-d245-4c47-9fb9-5dfe84a1284c", "type": "concept", "title": "Supported decision-making"}]}, {"id": "c2bedbda-5e0b-425c-86b4-809c06f3058f", "type": "subtopic", "title": "Surrogates and advance planning", "description": "When patients cannot decide, clinicians need ethically grounded processes.", "children": [{"id": "362ed57f-b839-48b5-91e7-6333bbd69269", "type": "concept", "title": "Advance directives"}, {"id": "1c78cdf4-27f0-4a39-a876-af65854c0319", "type": "concept", "title": "Substituted judgment and best interests"}, {"id": "109775f4-a56c-429d-af32-0d28667ab2a1", "type": "concept", "title": "Hierarchy of surrogates and conflict management"}]}]}, {"id": "629ff812-7a46-4882-b630-320caaa285cf", "type": "topic", "title": "Confidentiality, HIPAA, Privacy, and Trust", "description": "This module treats privacy as both a legal requirement and a moral foundation of the therapeutic relationship.", "children": [{"id": "7aa23363-12a7-4da9-8c91-0898c53831a6", "type": "subtopic", "title": "Confidentiality", "description": "Patients need trust that sensitive information will be protected.", "children": [{"id": "127c876f-16ed-414a-a844-7088acd3e666", "type": "concept", "title": "Professional confidentiality"}, {"id": "f3615045-92bb-4993-a1c0-7e078faa6728", "type": "concept", "title": "Minimum necessary disclosure"}, {"id": "a85dad5f-6435-43ae-ac15-65f8bd8f6f32", "type": "concept", "title": "Privacy in team care and teaching settings"}]}, {"id": "55b702a1-3391-4b0c-91d9-a6324286b726", "type": "subtopic", "title": "HIPAA and patient rights", "description": "Students learn the legal baseline for protected health information.", "children": [{"id": "d0701626-5b52-42db-bc48-b11b5e32fe31", "type": "concept", "title": "Protected health information"}, {"id": "b22684bd-243a-4c43-87c3-3c61a22ac704", "type": "concept", "title": "Access, amendment, and accounting concepts"}, {"id": "75d950c9-1a54-498f-ab71-24612a576e71", "type": "concept", "title": "Permitted uses and disclosures"}]}, {"id": "be801129-1e01-4bec-9de6-3489f8a6fdaf", "type": "subtopic", "title": "Privacy dilemmas", "description": "Privacy is tested by technology, families, safety, and public duties.", "children": [{"id": "bb47177a-6647-4718-9727-9e51b029bedf", "type": "concept", "title": "Adolescents and family access"}, {"id": "20e3398c-77a2-4f2f-a45e-ee330f15a33f", "type": "concept", "title": "Mandatory reporting"}, {"id": "dbb6fb21-b064-49ca-a971-73320f6e6046", "type": "concept", "title": "EHR snooping, social media, and data sharing"}]}]}, {"id": "08583c41-7daa-40a7-840a-a7198f55c117", "type": "topic", "title": "Truth-Telling, Communication, Disclosure, and Difficult Conversations", "description": "Students learn the ethics of honesty, prognosis, error disclosure, breaking bad news, and respectful communication.", "children": [{"id": "94633371-27ee-4276-996f-efc8bb1d6d22", "type": "subtopic", "title": "Truth-telling", "description": "Honesty must be compassionate, culturally responsive, and clinically useful.", "children": [{"id": "fc2dcd1b-f643-4a08-8c3b-5970c66d0002", "type": "concept", "title": "Diagnosis, prognosis, and uncertainty"}, {"id": "dd53f9ae-f22a-42c3-a3f4-39f2517b7e4e", "type": "concept", "title": "Hope and realism"}, {"id": "468e16a8-3967-4a79-ba42-558abca60959", "type": "concept", "title": "Requests not to disclose"}]}, {"id": "f50bb9a7-7afa-48af-a51a-24ba251709a5", "type": "subtopic", "title": "Error disclosure", "description": "Patients deserve transparency when harm occurs.", "children": [{"id": "29edb3d8-31ec-4a02-99d6-70f8db48335b", "type": "concept", "title": "Disclosure, apology, explanation, and prevention"}, {"id": "cee075f8-fca3-4779-8caf-a34f4b1e3831", "type": "concept", "title": "Just culture"}, {"id": "4bea251b-381d-439c-b65c-8a6cfc728995", "type": "concept", "title": "Documentation and institutional policy"}]}, {"id": "514e9a12-9332-4a38-9edd-907f6c6b8255", "type": "subtopic", "title": "Difficult conversations", "description": "Ethics often happens through communication under stress.", "children": [{"id": "d9150cd4-36ca-4b23-b5d9-2ea0f85d7dfc", "type": "concept", "title": "Breaking bad news"}, {"id": "f1c0740d-9155-4b0f-a6bc-f23e1df39b73", "type": "concept", "title": "Goals-of-care conversations"}, {"id": "434e13de-1e21-40ec-b0bf-3e1bdf032c69", "type": "concept", "title": "Interpreter use and language access"}]}]}, {"id": "573daa3b-f3ce-4722-a1c2-e9f35d247654", "type": "topic", "title": "End-of-Life Ethics, Palliative Care, and Medical Aid-in-Dying Debates", "description": "This topic examines withholding and withdrawing treatment, advance directives, goals of care, suffering, and contested end-of-life practices.", "children": [{"id": "642f26db-3176-4b29-97e7-e4fe8a476e66", "type": "subtopic", "title": "Withholding and withdrawing treatment", "description": "Students learn why non-initiation and discontinuation can be ethically equivalent.", "children": [{"id": "adcbb843-5497-4113-a20a-2825651dc94c", "type": "concept", "title": "Medical futility debates"}, {"id": "627414d1-c2e2-482a-8028-afc6de096976", "type": "concept", "title": "Burden-benefit analysis"}, {"id": "8733f23c-b9b6-45aa-8707-f45017263d24", "type": "concept", "title": "Life-sustaining treatment decisions"}]}, {"id": "2d6ffa58-519c-4102-a3ac-7868f4515d5a", "type": "subtopic", "title": "Palliative care and suffering", "description": "Relief of suffering is a central ethical duty.", "children": [{"id": "2e32ace4-8468-4e75-9b98-dc8a854d5f53", "type": "concept", "title": "Pain control and symptom management"}, {"id": "e0019177-3ff4-4be8-bf7c-4eff6b8c4dbe", "type": "concept", "title": "Doctrine of double effect"}, {"id": "f938f979-fb6a-44d7-9f7f-8bb17051c147", "type": "concept", "title": "Palliative sedation"}]}, {"id": "e62cd3d2-7e67-4da1-92be-c30eb1642b47", "type": "subtopic", "title": "Contested end-of-life issues", "description": "Students analyze disagreement with care and precision.", "children": [{"id": "b021b24d-fa7b-43ea-b2b3-a82eea6b0c3d", "type": "concept", "title": "DNR orders and POLST/MOLST"}, {"id": "6656821d-013c-46e4-ae86-d0c93c80f8f2", "type": "concept", "title": "Brain death and organ donation"}, {"id": "809e9a44-f572-4bf8-be87-1ffcb6aa1682", "type": "concept", "title": "Medical aid-in-dying debates and jurisdictional variation"}]}]}, {"id": "86159cd3-889d-4e3b-b7c0-5e145aac34fd", "type": "topic", "title": "Reproductive, Sexual, and Family Ethics", "description": "Students examine ethical conflicts around reproduction, pregnancy, contraception, fertility, neonatal care, and family decision-making.", "children": [{"id": "daab4bea-2d5d-4f1e-8a5a-b09ff821077d", "type": "subtopic", "title": "Reproductive autonomy", "description": "Students examine ethically complex decisions around reproduction and pregnancy.", "children": [{"id": "386c0725-7c6a-4b2e-8718-579026eb853a", "type": "concept", "title": "Contraception and sterilization"}, {"id": "86afda9e-a0f8-47a6-9cd5-c204479f2e7e", "type": "concept", "title": "Abortion ethics and legal variation"}, {"id": "5801f638-c746-416a-90fc-e8035ae9b385", "type": "concept", "title": "Fertility treatment and embryo disposition"}]}, {"id": "08e65612-42c9-4bcd-a825-e99b64e0a4cc", "type": "subtopic", "title": "Maternal-fetal ethics", "description": "Pregnancy can create real or perceived conflicts between patients and fetuses.", "children": [{"id": "7c727440-b527-478f-9237-fa3f48e73826", "type": "concept", "title": "Refusal of recommended treatment"}, {"id": "79a89662-db6b-4b59-bc16-20020b793a33", "type": "concept", "title": "Substance use and punitive policies"}, {"id": "a19a0ba3-e33f-41db-9503-47877e2fd632", "type": "concept", "title": "Respectful maternity care"}]}, {"id": "82f9c0c2-7588-4d1c-ba1b-2a7c437192f8", "type": "subtopic", "title": "Family and neonatal ethics", "description": "Families often participate in morally weighty decisions.", "children": [{"id": "37cb6b79-8174-454b-8631-dd7b8c986fc5", "type": "concept", "title": "NICU decision-making"}, {"id": "b249be5a-5847-4b4e-b1c6-29dcf23d6527", "type": "concept", "title": "Genetic testing in children"}, {"id": "48f7daeb-6f46-4a81-a883-511818690a41", "type": "concept", "title": "Family disagreement and best interests"}]}]}, {"id": "af65a085-2676-4e47-8967-a82f9a6b6112", "type": "topic", "title": "Pediatric, Geriatric, Disability, and Vulnerable-Population Ethics", "description": "This topic asks how vulnerability, dependency, disability, age, and voice affect ethical obligations and decision processes.", "children": [{"id": "73fb9845-84fc-4439-b1bb-93f200ac5839", "type": "subtopic", "title": "Pediatric ethics", "description": "Children require protection and respect for developing autonomy.", "children": [{"id": "5f0c5f57-36c0-4185-ad66-2eff520923d3", "type": "concept", "title": "Assent and permission"}, {"id": "598e7972-bd1b-49ad-bccb-07a290842bd7", "type": "concept", "title": "Best interests standard"}, {"id": "17cac7ab-0e15-48fe-8085-6dd190b79039", "type": "concept", "title": "Mature minor issues"}]}, {"id": "e7501b76-0afc-403d-bc16-868326cf647b", "type": "subtopic", "title": "Geriatric ethics", "description": "Older adults face distinctive risks of paternalism and neglect.", "children": [{"id": "b4e933cb-812c-4952-a240-7f2281cf6162", "type": "concept", "title": "Capacity and cognitive impairment"}, {"id": "d8ab8690-0ce1-44cf-83e2-ef0af6afe297", "type": "concept", "title": "Elder abuse and neglect"}, {"id": "177634d4-8719-472c-b3aa-d459fe15f880", "type": "concept", "title": "Long-term care and quality of life"}]}, {"id": "a267b55f-6a7d-4b8f-b710-6efbdb831560", "type": "subtopic", "title": "Disability and vulnerability", "description": "Ethical care must avoid ableism and protect voice.", "children": [{"id": "3bab42de-f33d-4daf-b810-cfd2f464ea63", "type": "concept", "title": "Quality-of-life assumptions"}, {"id": "e6f65942-3d87-4cd1-9a20-120746a8c5e3", "type": "concept", "title": "Communication access"}, {"id": "e8aa2cb5-bf20-4f4b-98e9-180a6f5ca0e0", "type": "concept", "title": "Supported decision-making and accommodations"}]}]}, {"id": "550dc87e-792a-4cc1-9c52-e437bab8e740", "type": "topic", "title": "Research Ethics, IRBs, Consent, and Human Subjects Protection", "description": "Students learn the history and principles of human-subjects protection, including Belmont, consent, risk-benefit review, and justice.", "children": [{"id": "b13118a1-c254-42bb-aa04-d3dc9d2ba7e3", "type": "subtopic", "title": "Belmont principles", "description": "Research ethics begins with respect for persons, beneficence, and justice.", "children": [{"id": "fffee5b0-bbcd-4f73-abb9-974a2cc8d73f", "type": "concept", "title": "Informed consent"}, {"id": "fed5b86b-97fd-4815-8097-41aef0888040", "type": "concept", "title": "Risk-benefit assessment"}, {"id": "b155ce36-72df-42ce-b050-12f86cc03d05", "type": "concept", "title": "Fair subject selection"}]}, {"id": "428a4894-a28c-4c34-9a0e-1a7d17f3b9d2", "type": "subtopic", "title": "IRB and oversight", "description": "Students learn how research is reviewed and monitored.", "children": [{"id": "52ca5e14-c803-4fdc-b599-d240c958084e", "type": "concept", "title": "IRB review categories"}, {"id": "99fdaa80-bc1b-4995-8eab-3b7de8df5959", "type": "concept", "title": "Vulnerable populations"}, {"id": "aafc2155-edbe-4667-be52-37d88fde2229", "type": "concept", "title": "Adverse events and continuing review"}]}, {"id": "539df6ef-b519-4265-b231-b85fb516883a", "type": "subtopic", "title": "Historical and contemporary cases", "description": "Cases show why protections matter.", "children": [{"id": "addf76fa-411b-4fe1-9633-882193d72d86", "type": "concept", "title": "Tuskegee syphilis study"}, {"id": "e933e5e7-aaba-494f-b7d3-879c5c700f09", "type": "concept", "title": "Henrietta Lacks and biospecimens"}, {"id": "04b01ed4-42ae-4fb3-aedd-5d4d90d69ca4", "type": "concept", "title": "Genomics, biobanks, and community consent"}]}]}, {"id": "cf5989b0-e6d6-44cb-80aa-3f79819f9ecf", "type": "topic", "title": "Resource Allocation, Triage, and Distributive Justice", "description": "This module examines scarcity, rationing, triage, organ allocation, insurance constraints, and fairness in individual and population decisions.", "children": [{"id": "dbc714ad-8703-4f81-a8b2-b7380655a8f6", "type": "subtopic", "title": "Scarcity and rationing", "description": "Healthcare ethics must address limited resources honestly.", "children": [{"id": "85e8b60f-167f-4496-b979-b0e72429f974", "type": "concept", "title": "Beds, staff, medications, organs, vaccines, and ICU capacity"}, {"id": "3bf927bc-d813-4651-9a16-d028185aef81", "type": "concept", "title": "Explicit versus implicit rationing"}, {"id": "5bf85c70-4ab1-47ec-97fa-c48f61c7c899", "type": "concept", "title": "Transparency and consistency"}]}, {"id": "7a68b308-1541-4e5e-b1c9-30db9019752e", "type": "subtopic", "title": "Allocation principles", "description": "Students compare fairness frameworks.", "children": [{"id": "280a147b-e3ce-404e-b38e-e3c1bacc358d", "type": "concept", "title": "Need, benefit, urgency, prognosis, lottery, and first-come-first-served"}, {"id": "ae96ff47-46b5-4999-b881-d5327f50ad3c", "type": "concept", "title": "Maximizing benefit versus protecting the worst off"}, {"id": "46531b7f-dc3e-4b4f-a15f-84d79bae2740", "type": "concept", "title": "Procedural justice"}]}, {"id": "932d88fe-10f5-4259-803a-9cdf26106fa9", "type": "subtopic", "title": "Triage cases", "description": "Students practice applying principles under pressure.", "children": [{"id": "2f269895-33c5-4ad3-bbbe-51318b718390", "type": "concept", "title": "Crisis standards of care"}, {"id": "7cc0cdb1-4869-4b6e-bd3b-c816a24f4046", "type": "concept", "title": "Organ transplantation"}, {"id": "8700c4fe-665d-4b08-9a9a-ee9599ddd21a", "type": "concept", "title": "Insurance and coverage decisions"}]}]}, {"id": "87b4535e-fcb8-44a2-9467-27511590f047", "type": "topic", "title": "Health Equity, Structural Racism, Bias, and Cultural Humility", "description": "Students connect ethics to inequity, implicit bias, structural racism, cultural humility, and the duty to provide equitable care.", "children": [{"id": "81de5ee6-f18f-4b06-8721-edf3541cdc3f", "type": "subtopic", "title": "Health disparities", "description": "Ethics includes the obligation to recognize unequal burdens and outcomes.", "children": [{"id": "406c3758-cf0c-43f7-994c-ccfc84bb45f9", "type": "concept", "title": "Race, ethnicity, gender, disability, class, geography, and language"}, {"id": "176c9754-c3d9-41a7-9834-9